INSERT INTO "PlatformSetting" (id, key, value, "updatedAt")
VALUES (
  gen_random_uuid()::text,
  'faq',
  '[{"question":"How do I register as a new owner?","answer":"Go to the Register page and fill in your full name, phone number (10-digit Indian mobile starting with 6-9), username (4-20 characters using letters, numbers, dots, or underscores), password, business name, city, and at least one location/village. Your request will be submitted for review by the Platform Admin."},{"question":"What are the password requirements for self-registration?","answer":"Your password must be at least 8 characters long, contain at least one uppercase letter, one number, and one special character."},{"question":"How long does registration approval take?","answer":"The Platform Admin reviews and approves or rejects registration requests. You will see a status message when you try to log in. Contact the platform admin if your request is delayed."},{"question":"Can I use the same phone number for multiple registrations?","answer":"The system flags duplicate phone numbers for the admin review, but it does not block registration. The Platform Admin makes the final decision on approval."},{"question":"What happens if my chosen username is already taken?","answer":"You will be notified immediately while typing. Choose a different username. Only letters, numbers, dots, and underscores are allowed (4-20 characters)."},{"question":"What happens after too many failed login attempts?","answer":"After 5 consecutive failed login attempts, your account is temporarily locked for 15 minutes. Wait for the lockout period to expire and try again with the correct password."},{"question":"How long does my login session last?","answer":"Sessions last up to 24 hours by default (configurable by the admin). Additionally, you are automatically logged out after 30 minutes of inactivity. The inactivity timeout can be configured per business (5 to 480 minutes)."},{"question":"Why am I asked to change my password on first login?","answer":"If your account was created by a Platform Admin or Business Owner (not self-registered), you must change the temporary password on first login for security. Self-registered users who chose their own password during registration are not required to do this."},{"question":"What is Two-Factor Authentication (2FA)?","answer":"Platform Admins and Owners are prompted to set up TOTP-based two-factor authentication (using apps like Google Authenticator) after their first password change. This adds an extra layer of security to your account. You will receive 8 recovery codes in case you lose access to your authenticator app."},{"question":"What user roles exist and what can each role do?","answer":"There are 4 roles: (1) Platform Admin manages owners, registration requests, and platform-wide settings. (2) Owner has full control over their businesses, users, customers, loans, payments, reports, and expenses. (3) Business Admin is similar to Owner but cannot create/deactivate businesses or grant support access. (4) Agent is limited to creating customers, posting payments, bulk posting, and viewing their own collection report in assigned villages only."},{"question":"Can an Agent see all customers and reports?","answer":"No. Agents can only see customers and data in the specific villages they are assigned to. They can only view their own collection report, not reports from other agents or the full business."},{"question":"How does the platform prevent unauthorized access?","answer":"All pages require authentication via a secure httpOnly cookie that cannot be accessed by JavaScript. Unauthenticated API requests receive a 401 error, and unauthenticated page requests are redirected to the login page. Every API endpoint verifies the user role and specific permissions before processing any action."},{"question":"What is role-based access control (RBAC)?","answer":"The system defines 36 distinct permission actions. Each user role is assigned a specific set of permissions. Before any action (creating a loan, posting a payment, viewing a report), the system checks that the logged-in user has the required permission. Unauthorized actions are blocked with a 403 Forbidden error."},{"question":"What is Support Access?","answer":"An Owner can grant time-limited access to the Platform Admin to view their business data for troubleshooting purposes. This access expires automatically after the set duration and can be revoked by the Owner at any time."},{"question":"Are API rate limits in place?","answer":"Yes. Registration is limited to 3 attempts per IP address per hour. Username availability checks are limited to 20 per IP per minute. Login is limited to 5 attempts per username before a 15-minute lockout. These limits protect against brute-force attacks and abuse."},{"question":"How is the Aadhaar number stored and protected?","answer":"Aadhaar numbers are never stored in plain text. The system stores a one-way SHA-256 hash of the full Aadhaar number (which cannot be reversed) and only keeps the last 4 digits in cleartext for display purposes (shown as XXXX XXXX 1234). This ensures that even if the database is compromised, full Aadhaar numbers cannot be recovered."},{"question":"How are passwords secured?","answer":"All passwords are hashed using bcrypt with 12 salt rounds, an industry-standard irreversible hashing algorithm. The original password is never stored. Session tokens are signed JWTs stored in httpOnly cookies that cannot be accessed by client-side JavaScript, preventing XSS-based token theft."},{"question":"Who can view customer personal information?","answer":"Only users with view_customer permission can view customer details. This includes Owners, Business Admins, and Agents. Agents are further restricted to customers in their assigned villages only. Platform Admins cannot see customer data unless the Owner grants them time-limited Support Access."},{"question":"Can I delete customer data?","answer":"Yes. Owners and Business Admins with the delete_customer permission can delete customer records. This is a permanent action."},{"question":"What fields are required to add a customer?","answer":"Full name (minimum 2 characters), phone number (10-digit Indian mobile starting with 6, 7, 8, or 9), and location/village are required. Optional fields include age (18-100), alternate phone, address, Aadhaar number (12 digits), job type, guarantor name and phone, notes, and photo."},{"question":"Can I have duplicate phone numbers for customers?","answer":"Yes, the system does not enforce phone uniqueness at the customer level within a business. Multiple customers can share the same phone number."},{"question":"How does customer rating work?","answer":"Customers are automatically rated on a 1-4 scale based on loan repayment history: Excellent (4) for on-time completion, Good (3) for minor delays within the good threshold, Average (2) for moderate delays, and Bad (1) for significant delays. Written-off loans always result in a Bad (1) rating. The overall customer rating is the average of all their loan ratings."},{"question":"What collection types are supported?","answer":"Three types: (1) Daily installments collected every working day (Sundays are skipped unless Collect on Sundays is enabled; holidays are also skipped). (2) Weekly installments collected on a specific day of the week. (3) Monthly installments collected on the same date each month (handles month-end overflow, e.g. 31st in February rolls to the last day)."},{"question":"What is the difference between ADDON and UPFRONT interest?","answer":"ADDON: The customer receives the full loan principal; interest is added on top. Total repayable = principal + interest. UPFRONT: Interest is deducted from the principal before disbursement; the customer receives less. Amount given = principal minus interest. Total repayable remains principal + interest."},{"question":"How is the installment schedule generated?","answer":"The system automatically generates a payment schedule based on the collection type, start date, and number of installments. For Daily loans, Sundays (unless enabled) and holidays are skipped. For Weekly loans, installments fall on the specified day. For Monthly loans, they fall on the same date. The last installment is adjusted for any rounding difference."},{"question":"What are the loan statuses?","answer":"Active: loan is within its expected collection period. Overdue: past the expected end date (up to 1 year). Defaulter: more than 1 year past the expected end date. Completed: fully paid (total paid equals total repayable)."},{"question":"Can I renew a loan?","answer":"Yes. When creating a new loan, you can link it to an existing active loan for renewal. The old loan is automatically marked as Completed, and the outstanding balance can be carried forward into the new loan calculation."},{"question":"What validation applies to the last installment?","answer":"The last installment must be a positive amount and cannot exceed 2x the regular installment amount. This validation prevents unreasonable balloon payments at the end of the loan."},{"question":"Can I post a payment for a future date?","answer":"No. Payment dates cannot be in the future. Payments must be for today or a past date."},{"question":"How far back can I backdate a payment?","answer":"Payments can be backdated up to 1 month (30 days). The payment date also cannot be before the loan start date."},{"question":"Can I overpay on a loan?","answer":"No. The payment amount cannot exceed the outstanding balance on the loan. When the total paid equals the total repayable amount, the loan is automatically marked as Completed."},{"question":"How does bulk payment posting work?","answer":"Select a village and payment date, then enter payment amounts for multiple active loans at once. Maximum 200 entries per bulk request. Duplicate loan entries in the same batch are not allowed. All payments in a batch are processed atomically, meaning either all succeed or none are saved."},{"question":"Can Agents edit payments?","answer":"Agents can only edit their own payments made on the same day. Owners and Business Admins can edit any payment, including payments made by others and on previous dates."},{"question":"What report types are available?","answer":"Six report types: Customers (list with status and details), Loans (with principal, interest, outstanding, and status filtering), Villages (location-wise summary with drill-down), Employees (staff activity and collection summary), Payments (transaction history with receipt details), and Collection Payslips (active loan collection slips). All reports require a date range."},{"question":"What export formats are supported?","answer":"Reports can be exported as Excel (XLSX) files with styled headers and formatting, or shared as PDF documents via WhatsApp."},{"question":"Can Agents view all reports?","answer":"No. Agents can only view their own collection report showing payments they have collected. Owners and Business Admins can view all report types for their businesses."},{"question":"What settings can I configure for my business?","answer":"Business name, city, receipt prefix (up to 5 uppercase letters), collection type, default collection day, interest model (ADDON/UPFRONT), Sunday collection toggle, grace periods for each collection type, customer rating thresholds, WhatsApp message template, and auto-logout timeout (5 to 480 minutes)."},{"question":"Can I add locations/villages after initial setup?","answer":"Yes. Owners and Business Admins can add new villages at any time. Village names must be unique within the business and between 2-100 characters. Agents can only see villages they are assigned to."},{"question":"What currency and units does the app use?","answer":"All monetary amounts are stored internally in paise (1/100 of Indian Rupee) for precision. Amounts are displayed in Rupees in the user interface."},{"question":"What timezone does the app use?","answer":"All dates and times operate in Indian Standard Time (IST, UTC+5:30). Date format used throughout the system is YYYY-MM-DD internally and DD/MM/YYYY for display."},{"question":"Can one owner see another owner business data?","answer":"No. Strict data isolation is enforced at the database query level. Each Owner can only access their own businesses and the data within them. The system checks ownership on every API request. An Owner cannot query, view, or modify any business, customer, loan, or payment belonging to another Owner. This is enforced server-side and cannot be bypassed through the interface."},{"question":"Can the Platform Admin see business data?","answer":"By default, no. The Platform Admin can only manage owners, registration requests, and platform settings. To view any business data, the Owner must explicitly grant time-limited Support Access. This access expires automatically and can be revoked at any time. Without an active, non-expired support access grant, the Platform Admin has zero visibility into any business data."},{"question":"How is business data isolated between owners?","answer":"Every API request passes through a scope-checking layer that verifies the requesting user has legitimate access to the specific business. Owners are matched by ownership records, Business Admins and Agents by their assignment records, and Platform Admins by active support access grants. Any mismatch results in an immediate Access Denied error. There is no global admin override. Not even Platform Admins can bypass this without an explicit grant from the Owner."},{"question":"What data backup options are available?","answer":"The application uses PostgreSQL as its production database, which supports standard backup mechanisms. Database backups can be taken using pg_dump for full or incremental backups. The Docker-based deployment allows for volume-level backups of the database data directory. For disaster recovery, regular automated backups should be configured at the server/infrastructure level by the system administrator."},{"question":"How is data protected against leakage?","answer":"Multiple layers of protection are in place: (1) All API endpoints require authentication and authorization checks. (2) Sensitive data like Aadhaar numbers are hashed (SHA-256) with only last 4 digits stored in cleartext. (3) Passwords use bcrypt with 12 salt rounds. (4) Session tokens are httpOnly cookies inaccessible to JavaScript. (5) Role-based access control with 36 granular permissions prevents unauthorized actions. (6) Business data isolation ensures cross-owner data cannot leak. (7) Rate limiting prevents brute-force enumeration attacks. (8) Agents are restricted to only their assigned villages. (9) Platform Admins require explicit owner-granted time-limited access to view any business data."},{"question":"What happens if someone tries to access data they are not authorized to view?","answer":"The system immediately returns a 403 Forbidden or Access Denied error. Unauthorized API requests are blocked before any data is retrieved. For unauthenticated requests, users are redirected to the login page or receive a 401 Unauthorized response. The scope-checking layer ensures that even valid logged-in users cannot access data outside their authorized scope."},{"question":"Is personal and financial data encrypted?","answer":"Sensitive personal data (Aadhaar numbers) is stored as irreversible SHA-256 hashes. Passwords use bcrypt hashing. Session tokens are cryptographically signed JWTs. The application is served over HTTPS (SSL/TLS) ensuring all data in transit is encrypted. For data at rest, encryption depends on the server/infrastructure configuration. PostgreSQL supports Transparent Data Encryption and disk-level encryption can be enabled at the OS level."}]',
  NOW()
)
ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, "updatedAt" = NOW();
